#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill. Deploys the Yozma MCP Worker.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Yozma MCP Worker deployment. Secret values are never read, echoed,
# stored or logged by this script: wrangler prompts for them itself (hidden).
# ──────────────────────────────────────────────────────────────────────────

MCP_URL="https://mcp.yozma.uz"
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
MCP_DIR="$ROOT/mcp"
KV_PLACEHOLDER="REPLACE_WITH_OAUTH_KV_ID"

# wr ARGS... runs wrangler from mcp/.
wr() { (cd "$MCP_DIR" && npx wrangler "$@"); }

# secret_exists NAME succeeds if the Worker already has that secret.
secret_exists() { wr secret list 2>/dev/null | grep -q "\"name\": *\"$1\""; }

# put_secret NAME: lets wrangler prompt for the value with hidden input.
put_secret() {
  local name="$1"
  if secret_exists "$name"; then
    if ! confirm "$name is already set. Replace it?"; then note "keeping existing $name"; return 0; fi
  fi
  step "Paste the value for $name when wrangler asks (input is hidden)."
  wr secret put "$name" || { SKIPPED+=("secret $name (cd mcp && npx wrangler secret put $name)"); warn "$name not set"; }
}

run_wizard() {

TOTAL_STAGES=8

banner "Yozma MCP Worker: setup"

# ── 1. Cloudflare login ───────────────────────────────────────────────────
stage "Cloudflare login"
say "Wrangler needs access to the Cloudflare account that hosts yozma.uz."
if wr whoami 2>/dev/null | grep -qi "associated with the email"; then
  say "Already logged in, so skipping."
else
  say "A browser window will open to authorise wrangler."
  wr login || { warn "wrangler login failed"; exit 1; }
fi
pause

# ── 2. KV namespace ───────────────────────────────────────────────────────
stage "KV namespace OAUTH_KV"
if ! grep -q "$KV_PLACEHOLDER" "$MCP_DIR/wrangler.jsonc"; then
  say "wrangler.jsonc already has a KV id, so skipping."
else
  say "Creating the KV namespace that stores OAuth sessions."
  out=$(wr kv namespace create OAUTH_KV 2>&1) || { printf '%s\n' "$out"; warn "namespace creation failed"; exit 1; }
  printf '%s\n' "$out"
  kv_id=$(printf '%s\n' "$out" | grep -Eo '[0-9a-f]{32}' | head -n1 || true)
  if [[ -z "$kv_id" ]]; then
    warn "couldn't parse the namespace id from the output above."
    ask kv_id "Paste the id:"
  fi
  if [[ ! "$kv_id" =~ ^[0-9a-f]{32}$ ]]; then warn "that doesn't look like a KV id (32 hex chars)"; exit 1; fi
  tmp=$(mktemp)
  sed "s/$KV_PLACEHOLDER/$kv_id/" "$MCP_DIR/wrangler.jsonc" > "$tmp" && cat "$tmp" > "$MCP_DIR/wrangler.jsonc"
  rm -f "$tmp"
  say "Wrote the id into mcp/wrangler.jsonc. Commit it later with git."
fi
pause

# ── 3. GitHub OAuth App ───────────────────────────────────────────────────
stage "GitHub OAuth App"
say "This lets only you (saidafzalkh) sign in to the MCP server."
open_url "https://github.com/settings/applications/new"
step "Application name: Yozma MCP"
step "Homepage URL: $MCP_URL"
step "Authorization callback URL: $MCP_URL/callback"
step "Click 'Register application'."
step "Click 'Generate a new client secret'. Keep this page open for stage 5."
pause "Done? Press Enter."

# ── 4. Fine-grained PAT ───────────────────────────────────────────────────
stage "GitHub fine-grained token"
say "The Worker commits posts and opens PRs with this token."
open_url "https://github.com/settings/personal-access-tokens/new"
step "Token name: yozma-mcp, pick an expiry you can live with."
step "Repository access: Only select repositories → saidafzalkh/yozma"
step "Permissions → Repository: Contents = Read and write"
step "Permissions → Repository: Pull requests = Read and write"
note "Metadata: Read-only is added automatically."
step "Click 'Generate token' and keep the page open for stage 5."
pause "Done? Press Enter."

# ── 5. Secrets ────────────────────────────────────────────────────────────
stage "Worker secrets"
say "wrangler asks for each value with hidden input. Nothing is saved locally."
note "Needs the Worker to exist for 'secret list' and 'secret put'; wrangler creates it if missing."
step "GITHUB_CLIENT_ID: Client ID from the OAuth App page."
put_secret GITHUB_CLIENT_ID
step "GITHUB_CLIENT_SECRET: the client secret you generated."
put_secret GITHUB_CLIENT_SECRET
step "GITHUB_TOKEN: the fine-grained token."
put_secret GITHUB_TOKEN
say "TAHRIRCHI_API_KEY enables the optional Uzbek spellcheck."
if confirm "Set TAHRIRCHI_API_KEY now? (No = skip)"; then
  put_secret TAHRIRCHI_API_KEY
else
  note "skipped; set it later with: cd mcp && npx wrangler secret put TAHRIRCHI_API_KEY"
fi
pause

# ── 6. Deploy ─────────────────────────────────────────────────────────────
stage "Deploy"
say "Deploying also creates the custom domain mcp.yozma.uz (DNS is on the same account)."
if confirm "Run wrangler deploy now?"; then
  wr deploy || { warn "deploy failed"; exit 1; }
else
  SKIPPED+=("deploy (cd mcp && npx wrangler deploy)")
fi
pause

# ── 7. Verify ─────────────────────────────────────────────────────────────
stage "Verify"
say "Waiting a moment can help: the new domain may need a minute for certificates."
code=$(curl -s -o /dev/null -w '%{http_code}' -X POST "$MCP_URL/mcp" || true)
if [[ "$code" == "401" ]]; then say "✓ POST /mcp → 401 (auth required)"
else warn "POST /mcp → $code (expected 401)"; SKIPPED+=("verify: POST $MCP_URL/mcp should return 401"); fi
code=$(curl -s -o /dev/null -w '%{http_code}' "$MCP_URL/.well-known/oauth-protected-resource/mcp" || true)
if [[ "$code" == "200" ]]; then say "✓ protected-resource metadata → 200"
else warn "protected-resource metadata → $code (expected 200)"; SKIPPED+=("verify: $MCP_URL/.well-known/oauth-protected-resource/mcp should return 200"); fi
if curl -s "$MCP_URL/.well-known/oauth-authorization-server" | grep -q "\"issuer\":\"$MCP_URL\""; then
  say "✓ authorization-server issuer is $MCP_URL"
else
  warn "authorization-server metadata has no issuer $MCP_URL"
  SKIPPED+=("verify: $MCP_URL/.well-known/oauth-authorization-server should contain issuer $MCP_URL")
fi
pause

# ── 8. Connect clients ────────────────────────────────────────────────────
stage "Connect your clients"
say "Server URL: $MCP_URL/mcp"
step "claude.ai: Settings → Connectors → Add custom connector → paste the URL."
step "ChatGPT: Settings → Apps & Connectors (or Plugins) → Advanced → Developer mode → add a custom MCP server with the same URL."
warn "On some ChatGPT plans write tools may be unavailable; check in the UI."
step "Claude Code: claude mcp add --transport http yozma $MCP_URL/mcp"
say "Sign in with GitHub as saidafzalkh when asked."
pause "Press Enter to finish."

finish
}

run_wizard "$@"; exit
